1	import * as THREE from "three";
2	import { ResponsiveRuntime } from "../../runtime/ResponsiveRuntime.js";
3	import { SceneObject } from "../../core/SceneObject.js";
4	import { GROUND_SHADER_DEFAULTS } from "../../config/ground.config.js";
5	import {
6	  createPointLightFromSpec,
7	  LightSpec,
8	} from "../env/SceneLights.js";
9	import type {
10	  GroundObjectOptions,
11	  GroundTweenProps,
12	} from "../../types/object.types.js";
13	import type {
14	  GroundRuntimePort,
15	  GroundRuntimeState,
16	} from "../../types/object-runtime.types.js";
17	import { Helpers } from "../../utils/Helpers.js";
18	import groundSurfaceVertexShader from "../../../shaders/ground/surface.vertex.glsl?raw";
19	import groundSurfaceFragmentShader from "../../../shaders/ground/surface.fragment.glsl?raw";
20	
21	const GROUND_MOUSE_TEXTURE_CHANNELS = 4;
22	const GROUND_MOUSE_TEXTURE_FADE = 0.94;
23	const GROUND_MOUSE_TEXTURE_RADIUS = 0.055;
24	const GROUND_MOUSE_TEXTURE_FALLOFF = 1.85;
25	const GROUND_DEFAULT_RESOLUTION = 1;
26	const GROUND_DEFAULT_POINTER = 0.5;
27	
28	export class Ground
29	  extends SceneObject<GroundTweenProps>
30	  implements GroundRuntimePort
31	{
32	  private _model: THREE.Group | null = null;
33	  private _panelLights: THREE.PointLight[] = [];
34	  private _options: Partial<GroundObjectOptions> = {};
35	  private _shaderMaterials: THREE.ShaderMaterial[] = [];
36	  private _shaderNoiseTexture: THREE.Texture | null = null;
37	  private _shaderNearestNoiseTexture: THREE.Texture | null = null;
38	  private _mouseTexture: THREE.DataTexture | null = null;
39	  private _mouseTextureData: Float32Array | null = null;
40	  private _mouseTextureSize: number = GROUND_SHADER_DEFAULTS.mouseTextureSize;
41	  private _elapsedTime = 0;
42	  private readonly _pointerUv = new THREE.Vector2(
43	    GROUND_DEFAULT_POINTER,
44	    GROUND_DEFAULT_POINTER,
45	  );
46	  private readonly _resolution = new THREE.Vector2(
47	    GROUND_DEFAULT_RESOLUTION,
48	    GROUND_DEFAULT_RESOLUTION,
49	  );
50	  private _pointerActive = false;
51	  private _pointerListenersAttached = false;
52	  private readonly _transitionColor = new THREE.Color();
53	  private readonly _lightColor = new THREE.Color();
54	  private readonly _darkColor = new THREE.Color();
55	  private _runtimeState: GroundRuntimeState = {};
56	  private readonly _onPointerMove = (event: PointerEvent): void => {
57	    if (typeof window === "undefined") return;
58	    const responsive = ResponsiveRuntime.getDefault().getSnapshot();
59	    const width = Math.max(
60	      GROUND_DEFAULT_RESOLUTION,
61	      responsive.viewportWidth,
62	    );
63	    const height = Math.max(
64	      GROUND_DEFAULT_RESOLUTION,
65	      responsive.viewportHeight,
66	    );
67	    this._pointerUv.set(event.clientX / width, 1 - event.clientY / height);
68	    this._pointerActive = true;
69	  };
70	  private readonly _onPointerLeave = (): void => {
71	    this._pointerActive = false;
72	  };
73	
74	  setOptions(props: Partial<GroundObjectOptions> | undefined): this {
75	    if (props != null) this._options = { ...this._options, ...props };
76	    return this;
77	  }
78	
79	  override getAnimationTarget(): THREE.Object3D | null {
80	    return this.getTimelineRoot();
81	  }
82	
83	  override getTweenApplyMode(): "gsapOnly" {
84	    return "gsapOnly";
85	  }
86	
87	  protected override getOptions(): Record<string, unknown> {
88	    return this._options;
89	  }
90	
91	  protected override applyVisibility(visible: boolean): void {
92	    const root = this.getTimelineRoot();
93	    if (root) root.visible = visible;
94	  }
95	
96	  protected override syncFromOptions(): void {
97	    this._syncTransform();
98	    if (this._model) this._applyMeshShadowSettings(this._model);
99	    this._syncShaderUniforms();
100	  }
101	
102	  override async runObject(): Promise<void> {
103	    const ctx = this._context;
104	    if (!ctx) return;
105	
106	    const modelUrl = this._options.modelUrl;
107	    if (!modelUrl) {
108	      return;
109	    }
110	
111	    try {
112	      await this._prepareShaderResources();
113	      const model = await ctx.loadModel(this.resolveAssetPath(modelUrl));
114	      const group = model as THREE.Group;
115	      this._model = group;
116	      this._applyMeshShadowSettings(group);
117	      this._applyGroundShader(group);
118	      this._attachPanelLights(group);
119	      this.attachToTimelineRoot(group, "groundRoot");
120	      this._syncTransform();
121	      this._syncShaderUniforms();
122	    } catch (error) {
123	    }
124	  }
125	
126	  override runUpdate(delta: number): void {
127	    this._elapsedTime += delta;
128	    this._updateResolution();
129	    this._updateMouseTexture();
130	    this._syncShaderUniforms();
131	  }
132	
133	  override dispose(): void {
134	    this._removePointerListeners();
135	    this._disposeShaderResources();
136	    this._disposeGroup(this._model);
137	    this._panelLights.length = 0;
138	    this._model = null;
139	    this._runtimeState = {};
140	    super.dispose();
141	  }
142	
143	  setRuntimeState(state: Partial<GroundRuntimeState>): void {
144	    this._runtimeState = { ...this._runtimeState, ...state };
145	    this._syncShaderUniforms();
146	  }
147	
148	  getRuntimeState(): GroundRuntimeState {
149	    return { ...this._runtimeState };
150	  }
151	
152	  private _applyMeshShadowSettings(group: THREE.Group): void {
153	    const cast = this._options.meshShadow?.cast;
154	    const receive = this._options.meshShadow?.receive;
155	    group.traverse((obj) => {
156	      if (!(obj instanceof THREE.Mesh)) return;
157	      obj.castShadow = cast ?? false;
158	      obj.receiveShadow = receive ?? false;
159	    });
160	  }
161	
162	  private _attachPanelLights(group: THREE.Group): void {
163	    const specs = this._options.panelLights ?? [];
164	    if (!specs.length) return;
165	
166	    const exactById = new Map(specs.map((spec) => [spec.id, spec as LightSpec]));
167	    const partialSpecs = specs
168	      .map((spec) => {
169	        const raw = (spec as LightSpec & { match?: string | string[] }).match;
170	        const tokens = Array.isArray(raw)
171	          ? raw
172	          : typeof raw === "string"
173	            ? [raw]
174	            : [];
175	        const normalized = tokens
176	          .map((token) => token.trim().toLowerCase())
177	          .filter((token) => token.length > 0);
178	        return { spec: spec as LightSpec, tokens: normalized };
179	      })
180	      .filter((entry) => entry.tokens.length > 0);
181	
182	    group.traverse((obj) => {
183	      if (!(obj instanceof THREE.Mesh)) return;
184	      const mat = obj.material;
185	      const matName =
186	        (Array.isArray(mat) ? mat[0]?.name : (mat as THREE.Material)?.name) ??
187	        "";
188	      const objName = obj.name ?? "";
189	      const names = [objName, matName]
190	        .map((name) => name.trim())
191	        .filter((name) => name.length > 0);
192	      const namesLower = names.map((name) => name.toLowerCase());
193	      const exactKey = names.find((name) => exactById.has(name));
194	      const partial = partialSpecs.find((entry) =>
195	        entry.tokens.some((token) =>
196	          namesLower.some((name) => name.includes(token)),
197	        ),
198	      );
199	      const spec = exactKey ? exactById.get(exactKey)! : partial?.spec;
200	      if (!spec) return;
201	
202	      if (
203	        !Number.isFinite(spec.color as number) ||
204	        !Number.isFinite(spec.intensity as number)
205	      ) {
206	        return;
207	      }
208	
209	      const light = createPointLightFromSpec(
210	        spec,
211	        Number(spec.color),
212	        Number(spec.intensity),
213	      );
214	      const position = spec.position ?? {};
215	      light.position.set(position.x ?? 0, position.y ?? 0, position.z ?? 0);
216	      light.name = `ground:${spec.id}`;
217	      obj.add(light);
218	      this._panelLights.push(light);
219	    });
220	  }
221	
222	  private _syncTransform(): void {
223	    const root = this.getTimelineRoot();
224	    if (!root) return;
225	    Helpers.applyTransform(root, this._options);
226	  }
227	
228	  private async _prepareShaderResources(): Promise<void> {
229	    this._disposeShaderResources();
230	    if (!this._isShaderEnabled()) return;
231	    const ctx = this._context;
232	    const noiseTextureUrl = this._options.shader?.noiseTextureUrl?.trim();
233	    if (!ctx?.loadTexture || !noiseTextureUrl) return;
234	    const noiseTexture = await ctx.loadTexture(this.resolveAssetPath(noiseTextureUrl));
235	    this._shaderNoiseTexture = noiseTexture;
236	    this._shaderNoiseTexture.wrapS = THREE.RepeatWrapping;
237	    this._shaderNoiseTexture.wrapT = THREE.RepeatWrapping;
238	    this._shaderNoiseTexture.magFilter = THREE.LinearFilter;
239	    this._shaderNoiseTexture.minFilter = THREE.LinearMipmapLinearFilter;
240	    this._shaderNoiseTexture.needsUpdate = true;
241	    ctx.prepareTexture?.(this._shaderNoiseTexture);
242	
243	    this._shaderNearestNoiseTexture = this._shaderNoiseTexture.clone();
244	    this._shaderNearestNoiseTexture.wrapS = THREE.RepeatWrapping;
245	    this._shaderNearestNoiseTexture.wrapT = THREE.RepeatWrapping;
246	    this._shaderNearestNoiseTexture.magFilter = THREE.NearestFilter;
247	    this._shaderNearestNoiseTexture.minFilter = THREE.NearestFilter;
248	    this._shaderNearestNoiseTexture.generateMipmaps = false;
249	    this._shaderNearestNoiseTexture.needsUpdate = true;
250	    ctx.prepareTexture?.(this._shaderNearestNoiseTexture);
251	
252	    this._mouseTextureSize = this._resolveMouseTextureSize();
253	    this._mouseTextureData = new Float32Array(
254	      this._mouseTextureSize *
255	        this._mouseTextureSize *
256	        GROUND_MOUSE_TEXTURE_CHANNELS,
257	    );
258	    this._mouseTexture = new THREE.DataTexture(
259	      this._mouseTextureData,
260	      this._mouseTextureSize,
261	      this._mouseTextureSize,
262	      THREE.RGBAFormat,
263	      THREE.FloatType,
264	    );
265	    this._mouseTexture.wrapS = THREE.ClampToEdgeWrapping;
266	    this._mouseTexture.wrapT = THREE.ClampToEdgeWrapping;
267	    this._mouseTexture.magFilter = THREE.LinearFilter;
268	    this._mouseTexture.minFilter = THREE.LinearFilter;
269	    this._mouseTexture.generateMipmaps = false;
270	    this._mouseTexture.needsUpdate = true;
271	    ctx.prepareTexture?.(this._mouseTexture);
272	    this._installPointerListeners();
273	  }
274	
275	  private _applyGroundShader(group: THREE.Group): void {
276	    this._shaderMaterials = [];
277	    if (!this._isShaderEnabled()) return;
278	    if (!this._shaderNoiseTexture || !this._shaderNearestNoiseTexture || !this._mouseTexture) {
279	      return;
280	    }
281	    const replacedMaterials = new Set<THREE.Material>();
282	    group.traverse((child) => {
283	      if (!(child instanceof THREE.Mesh)) return;
284	      const currentMaterials = Array.isArray(child.material)
285	        ? child.material
286	        : [child.material];
287	      if (currentMaterials.some((m) => m?.userData?.__groundShaderApplied)) {
288	        return;
289	      }
290	      for (const material of currentMaterials) replacedMaterials.add(material);
291	      child.material = this._createShaderMaterialSet(child.material);
292	    });
293	    for (const material of replacedMaterials) material.dispose();
294	  }
295	
296	  private _createShaderMaterialSet(
297	    material: THREE.Material | THREE.Material[],
298	  ): THREE.Material | THREE.Material[] {
299	    if (Array.isArray(material)) {
300	      return material.map((entry) => this._createShaderMaterial(entry));
301	    }
302	    return this._createShaderMaterial(material);
303	  }
304	
305	  private _createShaderMaterial(material: THREE.Material): THREE.Material {
306	    const nextMaterial = new THREE.ShaderMaterial({
307	      uniforms: {
308	        uGroundResolution: { value: this._resolution.clone() },
309	        uGroundTime: { value: this._elapsedTime },
310	        uGroundPage: { value: this._readShaderRuntimeValue("page") },
311	        uGroundScrollProgress: {
312	          value: this._readShaderRuntimeValue("scrollProgress"),
313	        },
314	        uGroundTransition: {
315	          value: this._readShaderRuntimeValue("transition"),
316	        },
317	        uGroundTransitionDirection: {
318	          value: this._readShaderRuntimeValue("transitionDirection"),
319	        },
320	        uGroundChapter: {
321	          value: this._readShaderRuntimeValue("chapter"),
322	        },
323	        uGroundTransitionColor: {
324	          value: this._transitionColor.clone(),
325	        },
326	        uGroundLightColor: {
327	          value: this._lightColor.clone(),
328	        },
329	        uGroundDarkColor: {
330	          value: this._darkColor.clone(),
331	        },
332	        tGroundNoise: { value: this._shaderNoiseTexture },
333	        tGroundNearestNoise: {
334	          value: this._shaderNearestNoiseTexture,
335	        },
336	        tGroundMouse: { value: this._mouseTexture },
337	      },
338	      vertexShader: groundSurfaceVertexShader,
339	      fragmentShader: groundSurfaceFragmentShader,
340	      transparent: false,
341	      depthTest: true,
342	      depthWrite: true,
343	      side: material.side,
344	    });
345	    nextMaterial.userData.__groundShaderApplied = true;
346	    this._shaderMaterials.push(nextMaterial);
347	    return nextMaterial;
348	  }
349	
350	  private _syncShaderUniforms(): void {
351	    if (this._shaderMaterials.length === 0) return;
352	    this._updateResolution();
353	    this._resolveShaderColors();
354	    const page = this._readShaderRuntimeValue("page");
355	    const scrollProgress = this._readShaderRuntimeValue("scrollProgress");
356	    const transition = this._readShaderRuntimeValue("transition");
357	    const transitionDirection = this._readShaderRuntimeValue(
358	      "transitionDirection",
359	    );
360	    const chapter = this._readShaderRuntimeValue("chapter");
361	    for (const material of this._shaderMaterials) {
362	      material.uniforms.uGroundResolution.value.copy(this._resolution);
363	      material.uniforms.uGroundTime.value = this._elapsedTime;
364	      material.uniforms.uGroundPage.value = page;
365	      material.uniforms.uGroundScrollProgress.value = scrollProgress;
366	      material.uniforms.uGroundTransition.value = transition;
367	      material.uniforms.uGroundTransitionDirection.value = transitionDirection;
368	      material.uniforms.uGroundChapter.value = chapter;
369	      material.uniforms.uGroundTransitionColor.value.copy(
370	        this._transitionColor,
371	      );
372	      material.uniforms.uGroundLightColor.value.copy(this._lightColor);
373	      material.uniforms.uGroundDarkColor.value.copy(this._darkColor);
374	    }
375	  }
376	
377	  private _readShaderRuntimeValue(
378	    key: "page" | "scrollProgress" | "transition" | "transitionDirection" | "chapter",
379	  ): number {
380	    const runtimeValue = this._runtimeState[key];
381	    if (typeof runtimeValue === "number" && Number.isFinite(runtimeValue)) {
382	      return runtimeValue;
383	    }
384	    const runtime = this._options.shader?.runtime;
385	    const fallback = GROUND_SHADER_DEFAULTS.runtime[key];
386	    const value = runtime?.[key];
387	    if (typeof value === "number" && Number.isFinite(value)) return value;
388	    return fallback;
389	  }
390	
391	  private _resolveMouseTextureSize(): number {
392	    const raw = this._options.shader?.mouseTextureSize;
393	    if (!Number.isFinite(raw)) return GROUND_SHADER_DEFAULTS.mouseTextureSize;
394	    return Math.max(8, Math.round(raw as number));
395	  }
396	
397	  private _resolveShaderColors(): void {
398	    const colors = this._options.shader?.colors;
399	    this._transitionColor.setHex(
400	      colors?.transition ?? GROUND_SHADER_DEFAULTS.colors.transition,
401	    );
402	    this._lightColor.setHex(colors?.light ?? GROUND_SHADER_DEFAULTS.colors.light);
403	    this._darkColor.setHex(colors?.dark ?? GROUND_SHADER_DEFAULTS.colors.dark);
404	  }
405	
406	  private _updateResolution(): void {
407	    if (typeof window === "undefined") {
408	      this._resolution.set(
409	        GROUND_DEFAULT_RESOLUTION,
410	        GROUND_DEFAULT_RESOLUTION,
411	      );
412	      return;
413	    }
414	    const snapshot = ResponsiveRuntime.getDefault().getSnapshot();
415	    this._resolution.set(
416	      Math.max(GROUND_DEFAULT_RESOLUTION, snapshot.viewportWidth),
417	      Math.max(GROUND_DEFAULT_RESOLUTION, snapshot.viewportHeight),
418	    );
419	  }
420	
421	  private _updateMouseTexture(): void {
422	    const mouseTexture = this._mouseTexture;
423	    const mouseTextureData = this._mouseTextureData;
424	    if (!mouseTexture || !mouseTextureData) return;
425	    for (
426	      let index = 0;
427	      index < mouseTextureData.length;
428	      index += GROUND_MOUSE_TEXTURE_CHANNELS
429	    ) {
430	      mouseTextureData[index] *= GROUND_MOUSE_TEXTURE_FADE;
431	      mouseTextureData[index + 1] *= GROUND_MOUSE_TEXTURE_FADE;
432	      mouseTextureData[index + 2] *= GROUND_MOUSE_TEXTURE_FADE;
433	      mouseTextureData[index + 3] = 1;
434	    }
435	    if (!this._pointerActive) {
436	      mouseTexture.needsUpdate = true;
437	      return;
438	    }
439	
440	    const size = this._mouseTextureSize;
441	    const pointerX = this._pointerUv.x * (size - 1);
442	    const pointerY = this._pointerUv.y * (size - 1);
443	    const radius = Math.max(1, Math.round(size * GROUND_MOUSE_TEXTURE_RADIUS));
444	
445	    for (let y = -radius; y <= radius; y += 1) {
446	      const pixelY = Math.round(pointerY + y);
447	      if (pixelY < 0 || pixelY >= size) continue;
448	      for (let x = -radius; x <= radius; x += 1) {
449	        const pixelX = Math.round(pointerX + x);
450	        if (pixelX < 0 || pixelX >= size) continue;
451	        const distance = Math.sqrt(x * x + y * y) / radius;
452	        if (distance > 1) continue;
453	        const strength = Math.pow(1 - distance, GROUND_MOUSE_TEXTURE_FALLOFF);
454	        const pixelIndex =
455	          (pixelY * size + pixelX) * GROUND_MOUSE_TEXTURE_CHANNELS;
456	        mouseTextureData[pixelIndex] = Math.max(
457	          mouseTextureData[pixelIndex],
458	          strength,
459	        );
460	        mouseTextureData[pixelIndex + 1] = Math.max(
461	          mouseTextureData[pixelIndex + 1],
462	          strength * 0.6,
463	        );
464	        mouseTextureData[pixelIndex + 2] = Math.max(
465	          mouseTextureData[pixelIndex + 2],
466	          strength * 0.85,
467	        );
468	      }
469	    }
470	
471	    mouseTexture.needsUpdate = true;
472	  }
