127	  [Engine, PageConfig],
128	  Promise<void>
129	> {
130	  private readonly _registry = new Map<string, ObjectRegistrationSpec>();
131	  private readonly _configRuntime = new ObjectConfigRuntime();
132	  private _disposed = false;
133	  private static readonly _ENV_ALIAS_BY_OBJECT_ID: Readonly<
134	    Partial<Record<keyof ObjectOptionsByKey, string>>
135	  > = {
136	    [sceneLights]: "env.light",
137	  };
138	
139	  constructor(registry: ObjectFactoryRegistry = createDefaultRegistry()) {
140	    for (const [id, spec] of Object.entries(registry)) {
141	      this._registry.set(id, spec);
142	    }
143	  }
144	
145	  registerFactory(id: string, spec: ObjectRegistrationSpec): void {
146	    this._registry.set(id, spec);
147	  }
148	
149	  register(id: string, spec: ObjectRegistrationSpec): void {
150	    this.registerFactory(id, spec);
151	  }
152	
153	  async init(engine: Engine, pageConfig: PageConfig): Promise<void> {
154	    if (this._disposed) return;
155	    for (const [id, spec] of this._getEnabledSpecs(pageConfig)) {
156	      const object = this._createConfiguredObject(
157	        spec,
158	        pageConfig.objectOptions,
159	        pageConfig.initialState,
160	      );
161	      await engine.setObject(id, object);
162	      this._registerEnvironmentAlias(engine, id as keyof ObjectOptionsByKey);
163	    }
164	  }
165	
166	  dispose(): void {
167	    if (this._disposed) return;
168	    this._disposed = true;
169	    this._registry.clear();
170	  }
171	
172	  private _getEnabledSpecs(
173	    pageConfig: PageConfig,
174	  ): Array<[string, ObjectRegistrationSpec]> {
175	    const enabledSpecs: Array<[string, ObjectRegistrationSpec]> = [];
176	    for (const [id, enabled] of Object.entries(pageConfig.objects)) {
177	      if (!enabled) continue;
178	      const spec = this._registry.get(id);
179	      if (!spec) continue;
180	      enabledSpecs.push([id, spec]);
181	    }
182	    return enabledSpecs;
183	  }
184	
185	  private _createConfiguredObject(
186	    spec: ObjectRegistrationSpec,
187	    pageOptions: PageConfig["objectOptions"] | undefined,
188	    initialState: PageConfig["initialState"] | undefined,
189	  ): SceneObject {
190	    const object = spec.create();
191	    const resolvedConfig = this._configRuntime.resolve(
192	      spec.id,
193	      pageOptions,
194	      initialState,
195	    );
196	    spec.applyOptions?.(object, resolvedConfig.options);
197	    if (resolvedConfig.effects && typeof object.setEffects === "function") {
198	      object.setEffects(resolvedConfig.effects);
199	    }
200	    return object;
201	  }
202	
203	  private _registerEnvironmentAlias(
204	    engine: Engine,
205	    objectId: keyof ObjectOptionsByKey,
206	  ): void {
207	    const envAlias = ObjectSetup._ENV_ALIAS_BY_OBJECT_ID[objectId];
208	    if (!envAlias) return;
209	    const target = engine.getObjectById(objectId as string);
210	    if (!target || typeof target !== "object") return;
211	    engine
212	      .getScene()
213	      .registerObject(envAlias, target as Record<string, unknown>);
214	  }
