16	const DEFAULT_BLOOM: Required<Omit<BloomOptions, "selective">> & {
17	  selective: boolean;
18	} = {
19	  strength: 0.12,
20	  radius: 0.35,
21	  threshold: 0.93,
22	  compositeStrength: 0.4,
