31	export class PostProcessor {
32	  private _renderer: THREE.WebGLRenderer;
33	  private _scene: THREE.Scene;
34	  private _camera: THREE.Camera;
35	  private _opts: PostProcessorOptions;
36	
37	  private _composer: EffectComposer | null = null;
38	  private _bloomComposer: EffectComposer | null = null;
39	  private _finalComposer: EffectComposer | null = null;
40	  private _bloomPass: UnrealBloomPass | null = null;
41	  private _blendPass: ShaderPass | null = null;
42	  private _vignettePass: ShaderPass | null = null;
43	  private _selective = false;
44	
45	  private _darkMaterial: THREE.MeshBasicMaterial | null = null;
46	  private _darkMaterialDepthOff: THREE.MeshBasicMaterial | null = null;
47	  private _materialCache = new Map<
48	    THREE.Object3D,
49	    THREE.Material | THREE.Material[]
50	  >();
51	  private _bloomDescendants = new Set<THREE.Object3D>();
52	  private _cachedBloomSignature = "";
53	  private _cachedNonBloomMeshes: THREE.Mesh[] = [];
54	  private _cachedSceneMeshes: THREE.Mesh[] = [];
55	  private _didWarnSelectiveFallback = false;
56	
57	  constructor(
58	    renderer: THREE.WebGLRenderer,
59	    scene: THREE.Scene,
60	    camera: THREE.Camera,
61	    opts: PostProcessorOptions = {},
62	  ) {
63	    this._renderer = renderer;
64	    this._scene = scene;
65	    this._camera = camera;
66	    this._opts = opts;
67	    this._setup();
68	  }
69	
70	  get isSelective(): boolean {
71	    return this._selective;
72	  }
73	
74	  private _setup(): void {
75	    const bloomOpt = this._opts.bloom;
76	    const vignetteOpt = this._opts.vignette;
77	    const hasBloom = bloomOpt !== false;
78	    const hasVignette = vignetteOpt !== false && vignetteOpt != null;
79	    if (!hasBloom && !hasVignette) {
80	      return;
81	    }
82	    const vignetteCfg = this._normalizeVignetteOptions(vignetteOpt);
83	    if (!hasBloom) {
84	      this._setupCustomPassPipeline(vignetteCfg);
85	      return;
86	    }
87	    const bloomCfg = this._normalizeBloomOptions(bloomOpt);
88	
89	    this._selective = bloomCfg.selective ?? true;
90	    const resolution = new THREE.Vector2(
91	      this._renderer.domElement.width,
92	      this._renderer.domElement.height,
93	    );
94	
95	    if (this._selective) {
96	      this._setupSelectiveBloom(bloomCfg, resolution, vignetteCfg);
97	      return;
98	    }
99	    this._setupGlobalBloom(bloomCfg, resolution, vignetteCfg);
100	  }
101	
102	  private _setupSelectiveBloom(
103	    cfg: Required<Omit<BloomOptions, "selective">> & { selective: boolean },
104	    resolution: THREE.Vector2,
105	    vignetteCfg: Required<VignetteOptions> | null,
106	  ): void {
107	    this._darkMaterial = new THREE.MeshBasicMaterial({ color: 0x000000 });
108	    this._darkMaterialDepthOff = new THREE.MeshBasicMaterial({
109	      color: 0x000000,
110	      depthTest: false,
111	      depthWrite: false,
112	    });
113	
114	    this._bloomComposer = new EffectComposer(this._renderer);
115	    this._bloomComposer.renderToScreen = false;
116	    this._bloomComposer.addPass(new RenderPass(this._scene, this._camera));
117	    this._bloomPass = new UnrealBloomPass(
118	      resolution,
119	      cfg.strength,
120	      cfg.radius,
121	      cfg.threshold,
122	    );
123	    this._bloomComposer.addPass(this._bloomPass);
124	
125	    this._finalComposer = new EffectComposer(this._renderer);
126	    this._finalComposer.addPass(new RenderPass(this._scene, this._camera));
127	
128	    const blendPass = new ShaderPass(
129	      new THREE.ShaderMaterial({
130	        uniforms: {
131	          baseTexture: { value: null },
132	          bloomTexture: {
133	            value: this._bloomComposer.renderTarget2.texture,
134	          },
135	          bloomMix: { value: cfg.compositeStrength },
136	        },
137	        vertexShader: additiveBlendVertexShader,
138	        fragmentShader: additiveBlendFragmentShader,
139	        defines: {},
140	      }),
141	      "baseTexture",
142	    );
143	    blendPass.needsSwap = true;
144	    this._blendPass = blendPass;
145	    this._finalComposer.addPass(blendPass);
146	    if (vignetteCfg) {
147	      this._vignettePass = this._createVignettePass(vignetteCfg);
148	      this._finalComposer.addPass(this._vignettePass);
149	    }
150	  }
151	
152	  private _setupGlobalBloom(
153	    bloomCfg: Required<Omit<BloomOptions, "selective">> & {
154	      selective: boolean;
155	    },
156	    resolution: THREE.Vector2,
157	    vignetteCfg: Required<VignetteOptions> | null,
158	  ): void {
159	    this._composer = new EffectComposer(this._renderer);
160	    this._composer.addPass(new RenderPass(this._scene, this._camera));
161	    this._bloomPass = new UnrealBloomPass(
162	      resolution,
163	      bloomCfg.strength,
164	      bloomCfg.radius,
165	      bloomCfg.threshold,
166	    );
167	    this._composer.addPass(this._bloomPass);
168	    if (vignetteCfg) {
169	      this._vignettePass = this._createVignettePass(vignetteCfg);
170	      this._composer.addPass(this._vignettePass);
171	    }
172	  }
173	
174	  private _setupCustomPassPipeline(
175	    vignetteCfg: Required<VignetteOptions> | null,
176	  ): void {
177	    this._composer = new EffectComposer(this._renderer);
178	    this._composer.addPass(new RenderPass(this._scene, this._camera));
179	    if (vignetteCfg) {
180	      this._vignettePass = this._createVignettePass(vignetteCfg);
181	      this._composer.addPass(this._vignettePass);
182	    }
183	  }
184	
185	  render(bloomRoots: Set<THREE.Object3D>, deltaTime?: number): void {
186	    if (!this._bloomPass) {
187	      if (this._composer) {
188	        this._composer.render(deltaTime);
189	        return;
190	      }
191	      this._renderer.render(this._scene, this._camera);
192	      return;
193	    }
194	
195	    if (this._selective) {
196	      const hasRoots = this._hasRenderableBloomRoots(bloomRoots);
197	      this._renderSelective(bloomRoots, hasRoots, deltaTime);
198	      return;
199	    }
200	    this._composer?.render(deltaTime);
201	  }
202	
203	  private _renderSelective(
204	    bloomRoots: Set<THREE.Object3D>,
205	    hasRoots: boolean,
206	    deltaTime?: number,
207	  ): void {
208	    if (
209	      !this._selective ||
210	      !this._bloomComposer ||
211	      !this._finalComposer ||
212	      !this._darkMaterial
213	    ) {
214	      this._composer?.render(deltaTime);
215	      return;
216	    }
217	    if (!hasRoots) {
218	      this._renderer.render(this._scene, this._camera);
219	      return;
220	    }
221	
222	    try {
223	      try {
224	        this._prepareBloomScene(hasRoots, bloomRoots);
225	        this._bloomComposer.render(deltaTime);
226	      } finally {
227	        this._restoreMaterials();
228	      }
229	      this._finalComposer.render(deltaTime);
230	    } catch (error) {
231	      if (!this._didWarnSelectiveFallback) {
232	        this._didWarnSelectiveFallback = true;
233	      }
234	      this._renderer.render(this._scene, this._camera);
235	    }
236	  }
237	
238	  private _prepareBloomScene(
239	    hasRoots: boolean,
240	    bloomRoots: Set<THREE.Object3D>,
241	  ): void {
242	    if (hasRoots) {
243	      this._darkenNonBloom(bloomRoots);
244	      return;
245	    }
246	    this._darkenAllMeshes();
247	  }
248	
249	  private _darkenNonBloom(bloomRoots: Set<THREE.Object3D>): void {
250	    this._materialCache.clear();
251	    const signature = this._createBloomSignature(bloomRoots);
252	    if (signature !== this._cachedBloomSignature) {
253	      this._cachedBloomSignature = signature;
254	      this._rebuildNonBloomMeshCache(bloomRoots);
255	    }
256	
257	    for (const mesh of this._cachedNonBloomMeshes) {
258	      this._materialCache.set(mesh, mesh.material);
259	      mesh.material = this._resolveDarkMaterial(mesh);
260	    }
261	  }
262	
263	  private _resolveDarkMaterial(mesh: THREE.Mesh): THREE.MeshBasicMaterial {
264	    const mat = mesh.material;
265	    const isDepthOff = Array.isArray(mat)
266	      ? mat.every((m) => m.depthTest === false)
267	      : (mat as THREE.Material).depthTest === false;
268	    return (isDepthOff ? this._darkMaterialDepthOff : this._darkMaterial)!;
269	  }
270	
271	  private _darkenAllMeshes(): void {
272	    const dark = this._darkMaterial!;
273	    this._materialCache.clear();
274	    if (this._cachedSceneMeshes.length === 0) {
275	      this._cachedSceneMeshes = this._collectSceneMeshes();
276	    }
277	    for (const mesh of this._cachedSceneMeshes) {
278	      this._materialCache.set(mesh, mesh.material);
279	      mesh.material = dark;
280	    }
281	  }
282	
283	  private _hasRenderableBloomRoots(bloomRoots: Set<THREE.Object3D>): boolean {
284	    if (bloomRoots.size === 0) return false;
285	    for (const root of bloomRoots) {
286	      if (root.parent) return true;
287	    }
288	    return false;
289	  }
290	
291	  private _normalizeBloomOptions(
292	    bloomOpt: PostProcessorOptions["bloom"],
293	  ): Required<Omit<BloomOptions, "selective">> & { selective: boolean } {
294	    if (typeof bloomOpt !== "object" || bloomOpt == null) {
295	      return { ...DEFAULT_BLOOM };
296	    }
297	    const strength = this._clampFinite(
298	      bloomOpt.strength,
299	      DEFAULT_BLOOM.strength,
300	      0,
301	      5,
302	    );
303	    const radius = this._clampFinite(
304	      bloomOpt.radius,
305	      DEFAULT_BLOOM.radius,
306	      0,
307	      2,
308	    );
309	    const threshold = this._clampFinite(
310	      bloomOpt.threshold,
311	      DEFAULT_BLOOM.threshold,
312	      0,
313	      2,
314	    );
315	    const compositeStrength = this._clampFinite(
316	      bloomOpt.compositeStrength,
317	      DEFAULT_BLOOM.compositeStrength,
318	      0,
319	      1,
320	    );
321	    const selective =
322	      typeof bloomOpt.selective === "boolean"
323	        ? bloomOpt.selective
324	        : DEFAULT_BLOOM.selective;
325	    return { strength, radius, threshold, compositeStrength, selective };
326	  }
327	
328	  private _normalizeVignetteOptions(
329	    vignetteOpt: PostProcessorOptions["vignette"],
330	  ): Required<VignetteOptions> | null {
331	    if (vignetteOpt === false || vignetteOpt == null) return null;
332	    if (vignetteOpt === true) return { ...DEFAULT_VIGNETTE };
333	    return {
334	      offset: this._clampFinite(
335	        vignetteOpt.offset,
336	        DEFAULT_VIGNETTE.offset,
337	        0,
338	        4,
339	      ),
340	      darkness: this._clampFinite(
341	        vignetteOpt.darkness,
342	        DEFAULT_VIGNETTE.darkness,
343	        0,
344	        4,
345	      ),
346	    };
347	  }
348	
349	  private _createVignettePass(
350	    vignetteCfg: Required<VignetteOptions>,
351	  ): ShaderPass {
352	    const pass = new ShaderPass(VignetteShader);
353	    pass.uniforms.offset.value = vignetteCfg.offset;
354	    pass.uniforms.darkness.value = vignetteCfg.darkness;
